import{z as l,x as B,o as r,c as d,q as o,j as A,D as a,d as n,s as i,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const R=JSON.parse('{"title":"QwQ","description":"","frontmatter":{"title":"QwQ","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/qwq.md","filePath":"llm/qwq.md","lastUpdated":1791413859000}'),p={name:"llm/qwq.md"};function c(Q,e,w,h,m,g){const t=B("Mermaid");return r(),d("div",null,[e[2]||(e[2]=o('<h1 id="qwq" tabindex="-1">QwQ <a class="header-anchor" href="#qwq" aria-label="Permalink to &quot;QwQ&quot;">​</a></h1><div class="epigraph"><p>在够厚的 32B 基座上放大基于结果的强化学习：数学用答案校验器，代码用测试用例，再短促地补一轮通用奖励，不必先上 671B 稀疏旗舰。</p><footer>—— Qwen Team，QwQ-32B: Embracing the Power of Reinforcement Learning，官方博客 2025-03-06；预览版见 QwQ-32B-Preview 博客 2024-11-27</footer></div><p>QwQ（Qwen with Questions，读音接近 quill）是通义的<strong>推理专线</strong>，不是 Qwen2.5-Instruct 换聊天模板。公开技术叙述以两篇官方博客为准：<strong>QwQ-32B-Preview</strong>（2024-11-27）展示长思维链在 GPQA / AIME / MATH-500 / LiveCodeBench 上的跳变；<strong>QwQ-32B</strong>（2025-03-06）把重点改成「强化学习如何放大」，并声称 32B 稠密可与 DeepSeek-R1（671B 总参、约 37B 激活）同桌。二者均 Apache 2.0 开源权重。团队<strong>没有</strong>为 QwQ 发布与 Qwen2.5 报告同级别的 arXiv 长文；架构数字以模型卡为准（Qwen2.5-32B 同系：64 层、GQA、RoPE、SwiGLU、RMSNorm、QKV bias、上下文 131072）。本篇写博客里实际承诺的训练故事与产品边界，不编造论文号，也不把 <a href="/llm/deepseek-r1">DeepSeek-R1</a> 的冷启动配方整段搬过来冒充 QwQ 原文。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>指令微调能让模型「看起来会逐步思考」，但逐步文本往往是模仿，不是被对错信号塑形过的搜索。竞赛数学与可测代码提供稀缺的<strong>可验证结果</strong>：答案对错、测试是否通过。若奖励来自学习型偏好模型，策略会讨好文风；若完全没有热启动，随机探索在 32B 上的样本效率可能不可接受。通义要回答的工程问题是：在已经用世界知识预训练过的 Qwen2.5 级基座上，<strong>只放大 RL</strong> 能否接近大一个数量级的稀疏推理模型；以及思维模型能否在思考过程中用工具、并根据环境反馈改推理。</p><p><span class="marginnote">术语翻译：RL（强化学习）就是让模型大量刷题——每题生成解答，对了加分、错了扣分，用分数调整参数。「可验证奖励」指对错由程序裁决（答案比对、测试用例通过与否），不像偏好模型那样靠「另一个模型的口味」打分，所以很难靠堆漂亮话骗分。</span></p><p>Preview 暴露了另一面：真开始「想很久」之后，会出现语种混杂、推理死循环、安全对齐不足、常识任务不强。这不是边角，而是长链生成的默认失败模式。正式版博客把 RL 分成「可验证域」与「通用域」两段，正是为了在抬数学代码的同时，用少量步数补指令遵循与智能体，并声称数学代码不明显回退。</p><h3 id="预览版与正式版不是同一叙事" tabindex="-1">预览版与正式版不是同一叙事 <a class="header-anchor" href="#预览版与正式版不是同一叙事" aria-label="Permalink to &quot;预览版与正式版不是同一叙事&quot;">​</a></h3><p>Preview 的公开数字：GPQA 65.2%、AIME 50%、MATH-500 90.6%、LiveCodeBench 50%（博客当时口径）。叙事是「给时间自问自答」。QwQ-32B 正式版对照 R1、R1 蒸馏的 Qwen-32B / Llama-70B、o1-mini，叙事换成「结果奖励可规模化」。不要把 Preview 的 AIME 50% 直接写成正式版分数，也不要把正式版的「可比 R1」写成架构创新。</p><p><span class="marginnote">Hugging Face 上的 <code>Qwen/QwQ-32B</code> 与 <code>Qwen/QwQ-32B-Preview</code> 是两个检查点。聊天模板会把思维过程与最终答案分栏（<code>reasoning_content</code> / <code>content</code>）。关掉思维、当普通 Instruct 用，会丢掉这根线存在的理由。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>正式版从<strong>冷启动检查点</strong>出发——博客未展开冷启动语料配方，只强调后续 RL 用结果奖励而非传统奖励模型来驱动数学与代码。数学侧：准确率校验器，只看最终解是否对。代码侧：执行服务器，看是否通过预定义测试。随 episode 增加，两域性能持续上升。第一段结束后，加第二段 <strong>通用能力 RL</strong>：奖励来自通用奖励模型加部分规则校验器。博客称少量步数即可抬指令遵循、人类偏好与智能体，同时数学代码无明显下降。</p><h3 id="工具嵌在思维链里" tabindex="-1">工具嵌在思维链里 <a class="header-anchor" href="#工具嵌在思维链里" aria-label="Permalink to &quot;工具嵌在思维链里&quot;">​</a></h3><p>智能体相关能力被写进推理模型：思考过程中调用工具，并根据环境反馈修改推理。这与 Qwen2.5-Instruct 的工具调用（见 <a href="/llm/function-calling">function calling</a>）目标不同——这里工具是长链推理的中间步，不是「决定了再调一次 API 就结束」。</p><h3 id="推理接口把思维与答案分栏" tabindex="-1">推理接口把思维与答案分栏 <a class="header-anchor" href="#推理接口把思维与答案分栏" aria-label="Permalink to &quot;推理接口把思维与答案分栏&quot;">​</a></h3><p>推理配置以官方用例为准：<code>max_new_tokens</code> 可到 32768 量级；温度等采样超参见模型卡与博客附录，错误采样会放大死循环。服务可用 vLLM；DashScope 兼容接口把思维链流式打在 <code>reasoning_content</code>。</p><p><span class="marginnote">数字实例：32768 token 的预算意味着一道难题的「内心独白」可以有数万字，是普通聊天回复的几十倍——延迟按秒计、费用按 token 计。给推理模型做产品要单独设超时与预算上限，不能沿用聊天机器人的默认值。</span></p>',17)),(r(),A(s,null,{default:a(()=>[i(t,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20CS%5B%22%E5%86%B7%E5%90%AF%E5%8A%A8%E6%A3%80%E6%9F%A5%E7%82%B9%EF%BC%88%E5%8D%9A%E5%AE%A2%E6%9C%AA%E5%B1%95%E5%BC%80%E9%85%8D%E6%96%B9%EF%BC%89%22%5D%20--%3E%20RL1%5B%22%E7%BB%93%E6%9E%9C%E5%A5%96%E5%8A%B1%20RL%EF%BC%9A%E6%95%B0%E5%AD%A6%E6%A0%A1%E9%AA%8C%20%2B%20%E4%BB%A3%E7%A0%81%E6%B5%8B%E8%AF%95%22%5D%0A%20%20RL1%20--%3E%20RL2%5B%22%E9%80%9A%E7%94%A8%20RM%20%2B%20%E8%A7%84%E5%88%99%E6%A0%A1%E9%AA%8C%EF%BC%8C%E5%B0%91%E9%87%8F%E6%AD%A5%22%5D%0A%20%20RL2%20--%3E%20AGT%5B%22%E6%80%9D%E8%80%83%E4%B8%AD%E8%B0%83%E7%94%A8%E5%B7%A5%E5%85%B7%EF%BC%8C%E6%8C%89%E7%8E%AF%E5%A2%83%E5%8F%8D%E9%A6%88%E6%94%B9%E6%8E%A8%E7%90%86%22%5D%0A%20%20AGT%20--%3E%20QWQ%5B%22QwQ-32B%20%E5%BC%80%E6%BA%90%E6%9D%83%E9%87%8D%22%5D%0A%20%20PV%5B%22QwQ-32B-Preview%EF%BC%9A%E9%95%BF%E9%93%BE%E8%87%AA%E9%97%AE%22%5D%20-.-%3E%20CS%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E("h2",{id:"机制",tabindex:"-1"},[n("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=E("h3",{id:"博客没有把算法写成可复现公式",tabindex:"-1"},[n("博客没有把算法写成可复现公式 "),E("a",{class:"header-anchor",href:"#博客没有把算法写成可复现公式","aria-label":'Permalink to "博客没有把算法写成可复现公式"'},"​")],-1)),(r(),A(s,null,{default:a(()=>[i(t,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q%5B%22%E5%90%8C%E4%B8%80%E9%81%93%E9%A2%98%E6%89%B9%E9%87%8F%E9%87%87%E6%A0%B7%E5%A4%9A%E6%9D%A1%E8%A7%A3%E7%AD%94%22%5D%20--%3E%20V%7B%22%E6%A0%A1%E9%AA%8C%E5%99%A8%E5%88%A4%E5%88%86%22%7D%0A%20%20V%20--%20%22%E7%AD%94%E6%A1%88%E5%AF%B9%20%2F%20%E6%B5%8B%E8%AF%95%E8%BF%87%22%20--%3E%20G%5B%22%E6%AD%A3%E5%90%91%E5%A5%96%E5%8A%B1%22%5D%0A%20%20V%20--%20%22%E9%94%99%20%2F%20%E6%9C%AA%E9%80%9A%E8%BF%87%22%20--%3E%20N%5B%22%E6%97%A0%E5%A5%96%E5%8A%B1%E6%88%96%E8%B4%9F%E5%90%91%22%5D%0A%20%20G%20--%3E%20U%5B%22%E6%9B%B4%E6%96%B0%E7%AD%96%E7%95%A5%EF%BC%9A%E5%A4%9A%E8%B5%B0%E5%BE%97%E5%88%86%E8%B7%AF%E7%BA%BF%22%5D%0A%20%20N%20--%3E%20U%0A%20%20U%20--%3E%20Q%0A%20%20RM%5B%22%E9%A3%8E%E6%A0%BC%E5%81%8F%E5%A5%BD%E6%A8%A1%E5%9E%8B%22%5D%20-.%E8%A2%AB%E6%9B%BF%E4%BB%A3%EF%BC%9A%E9%9A%BE%E4%BD%9C%E5%81%87%E6%80%A7%E5%B7%AE.-%3E%20V%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[n(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=o('<p>结果奖励把优化目标从「像不像人类逐步写」拧到「最后对不对」。数学校验器是稀疏的序列级信号，策略必须自己发现可被校验器承认的中间形式（格式、单位、最终盒）。代码测试同样稀疏，但比风格 RM 难作假——过不了测例就没有正向奖励。这与 <a href="/llm/grpo">GRPO</a> / R1 路线同属「可验证域 RL」，但 <strong>QwQ 博客没有写出组相对公式、组大小或 KL 系数</strong>；实现细节不能从 R1 论文反推后写进 QwQ 名下。</p><p><span class="marginnote">直觉类比：数学校验器像只批「卷尾最终答案」的阅卷机——过程写得再花哨，尾答案不对就是零分。模型只好自己摸索出「能让校验机看懂的书写格式」：步骤清楚、单位齐全、答案放对位置。稀疏信号逼出来的自律，比逐句打分的老师更难糊弄。</span></p><p>第二段通用 RL 的作用是正则：纯竞赛奖励会把模型训成「只愿写长解答的竞赛机」，指令遵循与安全会掉。少量步 + 规则校验器是在用小的分布修正换回产品可用，而不是再训一个同等算力的对齐模型。智能体反馈把环境（解释器、检索）接到思维链里，使「想」和「试」交替；若工具始终失败，长链会退化成 Preview 里写过的递归空转。</p><p>Preview 的自问自答可以视为冷启动或行为先验：用户可见的长思维，是 RL 要放大的生成模式，而不是推理时另插的搜索算法（没有公开 MCTS 树）。</p><p><span class="marginnote">32B 对 671B「总参」的对比，有效算力应对齐激活与生成长度。R1 激活约 37B，QwQ 是满 32B 稠密；显存账对稠密 32B 友好，并不自动等于 decode FLOPs 更低——长思维会把生成 token 拉到数万。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>没有技术报告意味着：冷启动数据、奖励权重、是否用过程监督、安全如何补，都不可复现到论文精度。Preview 列出的四条限制——语种混合、递归循环、安全、常识——在正式版博客里没有逐条宣布「已关闭」，部署仍要截断、重复检测与安全层。数学代码强、开放域弱，是专线的取舍，不是暂时的 bug。</p><p>许可 Apache 2.0，可商用，但仍须按模型卡处理衍生与归因。评测应复现官方仓库脚本；第三方「已超越 R1」的截图随 Arena 与快照变化。Qwen3 之后的思考模式是另一代产品，不要回溯改写 QwQ。</p><p><span class="marginnote">若生成出现无终止的自我反驳，先降 <code>max_new_tokens</code>、检查采样、启用官方推荐的重复惩罚，而不是换更大的 72B Instruct 当「更强 QwQ」——Instruct 没有这条 RL 专线。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>QwQ 是 Qwen 的推理专线：Preview 展示长链反思，32B 正式版把叙事收成可验证域 RL 再加短通用 RL。</li><li>公开出处是两篇官方博客与模型卡，没有可引用的 QwQ 专有 arXiv。</li><li>数学用答案校验器、代码用测例；智能体在思考中用工具。架构同系 Qwen2.5-32B，窗口 128K 级。</li><li>Preview 的循环与混语仍是部署风险；不要与 Instruct 或 R1 蒸馏检查点混用分数。</li><li>出处：Qwen Team，<em>QwQ: Reflect Deeply on the Boundaries of the Unknown</em>（2024-11-27）；<em>QwQ-32B: Embracing the Power of Reinforcement Learning</em>（2025-03-06）。基座对照 Yang 等 Qwen2.5 Technical Report，arXiv:2412.15115。</li></ul>',11))])}const f=l(p,[["render",c]]);export{R as __pageData,f as default};
